     1→import { doc, DocumentData, DocumentReference, getDoc } from "firebase/firestore";
     2→import { settleTaskCompletion as settleWallet } from "@/lib/walletSettlement";
     3→
     4→type SettlementDecision = "approved" | "rejected";
     5→
     6→type SettlementContext = {
     7→  source: "postback" | "manual_admin_review";
     8→  actorId?: string;
     9→  actorName?: string;
    10→  reason?: string;
    11→  verifiedBy?: string;
    12→};
    13→
    14→type SettlementResult =
    15→  | { ok: true; applied: true; completionId: string; transactionId: string; decision: SettlementDecision }
    16→  | { ok: true; applied: false; completionId: string; reason: "already_processed" | "invalid_status" | "already_settled" };
    17→
    18→/** Adapter for postback flow — delegates to centralized wallet settlement. */
    19→export async function settleTaskCompletion(
    20→  completionRef: DocumentReference<DocumentData>,
    21→  decision: SettlementDecision,
    22→  context: SettlementContext
    23→): Promise<SettlementResult> {
    24→  const completionId = completionRef.id;
    25→  const completionSnap = await getDoc(completionRef);
    26→  if (!completionSnap.exists()) {
    27→    throw new Error("Task completion not found");
    28→  }
    29→
    30→  const data = completionSnap.data();
    31→  const userId = String(data.userId || "");
    32→  const reward = Number(data.reward || 0);
    33→  const action = decision === "approved" ? "approve" : "reject";
    34→
    35→  const result = await settleWallet(userId, completionId, reward, action, {
    36→    source: context.source,
    37→    actorId: context.actorId,
    38→    actorName: context.actorName,
    39→    reason: context.reason,
    40→    verifiedBy: context.verifiedBy,
    41→  });
    42→
    43→  if (!result.success) {
    44→    throw new Error(result.message || "Settlement failed");
    45→  }
    46→
    47→  if (!result.applied) {
    48→    const reason = result.message?.toLowerCase().includes("pending")
    49→      ? "invalid_status"
    50→      : "already_settled";
    51→    return { ok: true, applied: false, completionId, reason };
    52→  }
    53→
    54→  return {
    55→    ok: true,
    56→    applied: true,
    57→    completionId,
    58→    transactionId: result.transactionId || "",
    59→    decision,
    60→  };
    61→}
