**Full rules to paste** (copy everything):

```
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    function isAdmin() {
      return request.auth != null &&
        get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == "admin";
    }

    function isSignedIn() {
      return request.auth != null;
    }

    match /users/{userId} {
      allow read, write: if isSignedIn() && request.auth.uid == userId;
      allow read, write: if isAdmin();
    }

    match /tasks/{taskId} {
      allow read: if true;
      allow write: if isAdmin();
    }

    match /taskCompletions/{completionId} {
      allow create: if isSignedIn() && request.resource.data.userId == request.auth.uid;
      allow read:   if isSignedIn() && (resource.data.userId == request.auth.uid || isAdmin());
      allow update, delete: if isAdmin();
    }

    match /payouts/{payoutId} {
      allow create: if isSignedIn() && request.resource.data.userId == request.auth.uid;
      allow read:   if isSignedIn() && (resource.data.userId == request.auth.uid || isAdmin());
      allow update, delete: if isAdmin();
    }

    match /stats/{statId} {
      allow read:  if isSignedIn();
      allow write: if isAdmin();
    }

    match /device_fingerprints/{fpId} {
      allow create: if true;
      allow read, update, delete: if isAdmin();
    }

    match /banned_devices/{banId} {
      allow read:  if isSignedIn();
      allow write: if isAdmin();
    }

    match /banned_emails/{email} {
      allow read:  if true;
      allow write: if isAdmin();
    }

    match /settings/{docId} {
      allow read:  if isSignedIn();
      allow write: if isAdmin();
    }

    match /platforms/{platformId} {
      allow read: if isSignedIn();
      allow write: if isAdmin();
    }

    match /walletTransactions/{txId} {
      allow create, update, delete: if isAdmin();
      allow read: if isSignedIn() && (resource.data.userId == request.auth.uid || isAdmin());
    }

    match /withdrawals/{withdrawalId} {
      allow create: if isSignedIn() && request.resource.data.userId == request.auth.uid;
      allow read:   if isSignedIn() && (resource.data.userId == request.auth.uid || isAdmin());
      allow update, delete: if isAdmin();
    }

  }
}
```

