   139→  async function requestWithdrawal(
   140→    amount: number,
   141→    walletAddress: string,
   142→    currency: "USDT" | "USDC",
   143→    network: "TRC20" | "ERC20",
   144→    gasFee: number,
   145→    netAmount: number,
   146→    feePercent: number
