   149→    if (profile.balance < amount) throw new Error("Insufficient balance");
   150→
   151→    const pendingQ = query(
   152→      collection(db, "withdrawals"),
   153→      where("userId", "==", user.uid),
   154→      where("status", "==", "pending")
   155→    );
   156→    const pendingSnap = await getDocs(pendingQ);
   157→    if (!pendingSnap.empty) throw new Error("You already have a pending withdrawal request");
   158→
   159→    // Wallet uniqueness check — runs BEFORE saving
   160→    const { isDuplicate, allowedByAdmin } = await checkWalletUniqueness(walletAddress, user.uid);
   161→    if (isDuplicate && !allowedByAdmin) {
