   222→          })),
   223→          sameWalletUserCount: sameWalletOtherUsers.length,
   224→          fraudReasons,
   225→          read: false,
   226→          createdAt: serverTimestamp(),
   227→        });
   228→      }
   229→    }).catch(() => { /* non-blocking — never fail the withdrawal itself */ });
   230→
   231→    await fetchWithdrawals();
   232→    await refreshProfile();
   233→  }
