   235→  async function approveWithdrawal(id: string) {
   236→    const wRef = doc(db, "withdrawals", id);
   237→    const wSnap = await getDoc(wRef);
   238→    const wData = wSnap.data() as Withdrawal | undefined;
   239→    if (!wData) throw new Error("Withdrawal not found");
   240→    if (wData.status !== "pending") {
   241→      throw new Error(`Withdrawal already processed (${wData.status})`);
   242→    }
   243→
   244→    await updateDoc(wRef, { status: "approved", processedAt: serverTimestamp() });
   245→
   246→    await updateDoc(doc(db, "users", wData.userId), {
   247→      pendingBalance: increment(-wData.amount),
   248→    });
   249→    await fetchAllWithdrawals();
   250→  }
   251→
   252→  async function rejectWithdrawal(id: string, note?: string) {
   253→    const wRef = doc(db, "withdrawals", id);
   254→    const wSnap = await getDoc(wRef);
   255→    const wData = wSnap.data() as Withdrawal | undefined;
   256→    if (!wData) throw new Error("Withdrawal not found");
   257→    if (wData.status !== "pending") {
   258→      throw new Error(`Withdrawal already processed (${wData.status})`);
   259→    }
   260→
   261→    await updateDoc(wRef, { status: "rejected", processedAt: serverTimestamp(), note: note || "" });
   262→
   263→    await updateDoc(doc(db, "users", wData.userId), {
   264→      balance: increment(wData.amount),
   265→      pendingBalance: increment(-wData.amount),
   266→    });
   267→    await fetchAllWithdrawals();
   268→  }
   269→
   270→  useEffect(() => {
   271→    if (user) fetchWithdrawals();
   272→  }, [user]);
