   274→  return (
   275→    <WalletContext.Provider
   276→      value={{ withdrawals, allWithdrawals, loading, requestWithdrawal, fetchWithdrawals, fetchAllWithdrawals, approveWithdrawal, rejectWithdrawal }}
   277→    >
   278→      {children}
   279→    </WalletContext.Provider>
   280→  );
   281→}
