   252→
   253→export async function comparePlatformReport(
   254→  entries: PlatformReportEntry[]
   255→): Promise<ReportComparisonResult> {
   256→  const completionsSnap = await getDocs(collection(db, "taskCompletions"));
   257→
   258→  const ourApproved: Record<string, { userId: string; taskId: string; reward: number }> = {};
   259→  completionsSnap.docs.forEach((d) => {
   260→    if (d.data().status === "approved") {
   261→      const key = `${d.data().userId as string}:${d.data().taskId as string}`;
   262→      ourApproved[key] = {
   263→        userId: d.data().userId as string,
   264→        taskId: d.data().taskId as string,
   265→        reward: (d.data().reward as number) || 0,
   266→      };
   267→    }
   268→  });
   269→
   270→  const platformApproved = entries.filter((e) => e.status === "approved");
   271→  const platformRejected = entries.filter((e) => e.status === "rejected");
   272→
   273→  const platformMap: Record<string, PlatformReportEntry> = {};
   274→  platformApproved.forEach((e) => { platformMap[`${e.userId}:${e.taskId}`] = e; });
   275→
   276→  let matchedCount = 0;
   277→  let matchedAmount = 0;
   278→  const mismatchedItems: ReportComparisonResult["mismatchedItems"] = [];
   279→  const missingInPlatform: ReportComparisonResult["missingInPlatform"] = [];
   280→
   281→  Object.entries(ourApproved).forEach(([key, ours]) => {
   282→    const platform = platformMap[key];
   283→    if (!platform) {
   284→      missingInPlatform.push({ userId: ours.userId, taskId: ours.taskId, ourAmount: ours.reward });
   285→    } else if (Math.abs(platform.amount - ours.reward) > 0.0001) {
   286→      mismatchedItems.push({
   287→        userId: ours.userId,
   288→        taskId: ours.taskId,
   289→        ourAmount: ours.reward,
   290→        platformAmount: platform.amount,
   291→        reason: `Amount mismatch: we expected $${ours.reward.toFixed(5)}, platform paid $${platform.amount.toFixed(5)}`,
   292→      });
   293→    } else {
   294→      matchedCount++;
   295→      matchedAmount += ours.reward;
   296→    }
   297→  });
   298→
   299→  const totalPlatformApproved = platformApproved.reduce((s, e) => s + e.amount, 0);
   300→  const totalOurApproved = Object.values(ourApproved).reduce((s, e) => s + e.reward, 0);
   301→
   302→  return {
   303→    matchedCount,
   304→    matchedAmount,
   305→    mismatchedItems,
   306→    missingInPlatform,
   307→    rejectedByPlatform: platformRejected.map((e) => ({
   308→      userId: e.userId,
   309→      taskId: e.taskId,
   310→      amount: e.amount,
   311→      reason: e.reason || "Rejected by platform",
   312→    })),
   313→    totalPlatformApproved,
   314→    totalOurApproved,
   315→    isFullMatch:
   316→      mismatchedItems.length === 0 &&
   317→      missingInPlatform.length === 0 &&
   318→      Math.abs(totalPlatformApproved - totalOurApproved) < 0.001,
   319→  };
   320→}
